import { CourseCard } from './CourseCard'
import { bestSellerCourses } from '@/config/data'

export function CourseCarousel({ title = "Best sellers" }: { title?: string }) {
  const scrollRef = useRef<HTMLDivElement>(null)
  const [canScrollLeft, setCanScrollLeft] = useState(false)
  const [canScrollRight, setCanScrollRight] = useState(true)

  const checkScroll = () => {
    if (!scrollRef.current) return
    const { scrollLeft, scrollWidth, clientWidth } = scrollRef.current
    setCanScrollLeft(scrollLeft > 5)
    setCanScrollRight(scrollLeft < scrollWidth - clientWidth - 5)
  }

  const scroll = (dir: number) => {
    if (!scrollRef.current) return
    scrollRef.current.scrollBy({ left: dir * 320, behavior: 'smooth' })
  }

  return (
    <section className="py-12 md:py-16">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-end justify-between mb-8">
          <div>
            <h2 className="text-2xl sm:text-3xl md:text-4xl font-900 text-charcoal" style={{ fontFamily: 'var(--font-display)' }}>
              {title}
            </h2>
            <p className="text-muted mt-1 text-sm sm:text-base">Learn from the most popular courses on CreativeHub</p>
          </div>
          <div className="hidden sm:flex gap-2">
            <button
              onClick={() => scroll(-1)}
              disabled={!canScrollLeft}
              className="w-10 h-10 rounded-full border border-gray-200 hover:border-gray-400 flex items-center justify-center text-charcoal transition disabled:opacity-30 disabled:cursor-not-allowed"
              aria-label="Scroll left"
            >
              <ChevronLeft size={20} />
            </button>
            <button
              onClick={() => scroll(1)}
              disabled={!canScrollRight}
              className="w-10 h-10 rounded-full border border-gray-200 hover:border-gray-400 flex items-center justify-center text-charcoal transition disabled:opacity-30 disabled:cursor-not-allowed"
              aria-label="Scroll right"
            >
              <ChevronRight size={20} />
            </button>
          </div>
        </div>
        <div
          ref={scrollRef}
          onScroll={checkScroll}
          className="flex gap-5 overflow-x-auto no-scrollbar scroll-smooth pb-2"
        >
          {bestSellerCourses.map((course, i) => (
            <div key={i} className="min-w-[260px] sm:min-w-[280px] max-w-[300px] flex-shrink-0">
              <CourseCard {...course} badge="Best seller" />
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}

