import React, { useState, useMemo } from 'react'
import { createRoot } from 'react-dom/client'
import '@/styles/globals.css'
import { Header } from '@/components/Header'
import { Footer } from '@/components/Footer'
import { projects, sortOptions, timeFilters } from '@/config/data'
import { Heart, Eye, Trophy, ChevronDown } from 'lucide-react'

const creativeFields = [
  "All fields", "2D Animation", "3D", "Illustration", "Photography",
  "Graphic Design", "Watercolor Painting", "Embroidery", "Digital Art",
  "Typography", "Motion Graphics", "Branding", "Fashion Design"
]

function ProjectsPage() {
  const [sortBy, setSortBy] = useState("Featured")
  const [timeFilter, setTimeFilter] = useState("All time")
  const [fieldFilter, setFieldFilter] = useState("All fields")
  const [sortOpen, setSortOpen] = useState(false)

  const sortedProjects = useMemo(() => {
    const arr = [...projects]
    switch (sortBy) {
      case "Most liked": return arr.sort((a, b) => b.likes - a.likes)
      case "Most viewed": return arr.sort((a, b) => b.views - a.views)
      case "Most recent": return arr.reverse()
      default: return arr
    }
  }, [sortBy])

  return (
    <div className="min-h-screen flex flex-col grain">
      <Header />
      <main className="flex-1 bg-white">
        <div className="bg-charcoal text-white">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 md:py-20">
            <h1 className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-900 mb-3" style={{ fontFamily: 'var(--font-display)' }}>
              Community projects
            </h1>
            <p className="text-gray-300 text-base sm:text-lg max-w-xl">
              Discover inspiring work from our creative community around the world.
            </p>
          </div>
        </div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          <div className="flex flex-wrap items-center gap-3 mb-8 pb-6 border-b border-gray-100">
            <div className="relative">
              <button
                onClick={() => setSortOpen(!sortOpen)}
                className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-gray-200 rounded-lg text-sm font-semibold text-charcoal hover:border-gray-300 transition"
              >
                Sort: {sortBy} <ChevronDown size={14} />
              </button>
              {sortOpen && (
                <div className="absolute top-full left-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-xl py-1 z-20 min-w-[180px]">
                  {sortOptions.map(opt => (
                    <button
                      key={opt}
                      onClick={() => { setSortBy(opt); setSortOpen(false) }}
                      className={`block w-full text-left px-4 py-2 text-sm transition ${sortBy === opt ? 'text-brand font-semibold bg-brand/5' : 'text-charcoal hover:bg-surface'}`}
                    >
                      {opt}
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div className="flex flex-wrap gap-1.5">
              {timeFilters.map(tf => (
                <button
                  key={tf}
                  onClick={() => setTimeFilter(tf)}
                  className={`px-3 py-2 text-xs font-medium rounded-full border transition ${timeFilter === tf ? 'border-brand text-brand bg-brand/5' : 'border-gray-200 text-muted hover:border-gray-300'}`}
                >
                  {tf}
                </button>
              ))}
            </div>

            <div className="w-px h-6 bg-gray-200 hidden sm:block" />

            <div className="flex flex-wrap gap-1.5">
              {creativeFields.slice(0, 6).map(f => (
                <button
                  key={f}
                  onClick={() => setFieldFilter(f)}
                  className={`px-3 py-2 text-xs font-medium rounded-full border transition ${fieldFilter === f ? 'border-brand text-brand bg-brand/5' : 'border-gray-200 text-muted hover:border-gray-300'}`}
                >
                  {f}
                </button>
              ))}
              <button className="px-3 py-2 text-xs font-medium rounded-full border border-gray-200 text-muted hover:border-gray-300 transition">
                +{creativeFields.length - 6} more
              </button>
            </div>
          </div>

          <div className="columns-1 sm:columns-2 lg:columns-3 xl:columns-4 gap-5 space-y-5">
            {sortedProjects.map((project, i) => (
              <div
                key={`${project.title}-${i}`}
                className="break-inside-avoid group relative overflow-hidden rounded-xl bg-surface border border-gray-100 hover:shadow-xl transition-all duration-300"
              >
                <div className="relative overflow-hidden" style={{ height: project.height }}>
                  <img
                    src={project.image}
                    alt={project.title}
                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                    loading="lazy"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                  {project.winner && (
                    <div className="absolute top-3 left-3 flex items-center gap-1.5 bg-yellow-400 text-charcoal text-xs font-bold px-3 py-1.5 rounded-full shadow">
                      <Trophy size={14} /> Winner
                    </div>
                  )}
                  <div className="absolute bottom-0 left-0 right-0 p-4 translate-y-2 group-hover:translate-y-0 opacity-0 group-hover:opacity-100 transition-all duration-300">
                    <div className="flex items-center gap-3 text-white text-sm">
                      <span className="flex items-center gap-1">
                        <Heart size={14} /> {project.likes}
                      </span>
                      <span className="flex items-center gap-1">
                        <Eye size={14} /> {project.views.toLocaleString()}
                      </span>
                    </div>
                  </div>
                </div>
                <div className="p-4">
                  <h3 className="font-bold text-sm text-charcoal mb-1" style={{ fontFamily: 'var(--font-display)' }}>
                    {project.title}
                  </h3>
                  <p className="text-xs text-muted">{project.author}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>
      <Footer />
    </div>
  )
}

createRoot(document.getElementById('root')!).render(<ProjectsPage />)

